import java.util.*;
import java.io.*;

public class MaxFlowSolution {
    static class MaxFlow {
        int[] head;
        int total;
        int[] current;
        int[] dist;
        int u, v, s, t, src, sink;
        static class Edge {
            int v, next, cap;
        }
        Edge[] edges;

        public MaxFlow(int N) {
            head = new int[N];
            current = new int[N];
            dist = new int[N];
            edges = new Edge[111111];
            for (int i = 0; i < edges.length; i++) {
                edges[i] = new Edge();
            }
            init();
        }

        void add_edge(int u, int v, int cap) {
            edges[total] = new Edge();
            edges[total].v = v;
            edges[total].next = head[u];
            edges[total].cap = cap;
            head[u] = total++;
            edges[total] = new Edge();
            edges[total].v = u;
            edges[total].next = head[v];
            edges[total].cap = 0;
            head[v] = total++;
        }

        void init() {
            Arrays.fill(head, -1);
            total = 0;
        }

        boolean build_bfs() {
            Arrays.fill(dist, -1);
            System.arraycopy(head, 0, current, 0, head.length);
            dist[src] = 0;
            Queue<Integer> q = new LinkedList<>();
            q.offer(src);
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int i = head[u]; i != -1; i = edges[i].next) {
                    v = edges[i].v;
                    if (dist[v] == -1 && edges[i].cap > 0) {
                        dist[v] = dist[u] + 1;
                        q.offer(v);
                    }
                }
            }
            return dist[sink] != -1;
        }

        int send_flow(int u, int flow) {
            if (u == sink) return flow;
            int total_flow = 0, pushed;
            for (int &i = current[u]; i != -1; i = edges[i].next) {
                v = edges[i].v;
                if (dist[v] == dist[u] + 1 && edges[i].cap > 0) {
                    pushed = send_flow(v, Math.min(flow - total_flow, edges[i].cap));
                    if (pushed > 0) {
                        edges[i].cap -= pushed;
                        edges[i ^ 1].cap += pushed;
                        total_flow += pushed;
                        if (total_flow == flow) break;
                    }
                }
            }
            if (total_flow == 0) dist[u] = -1;
            return total_flow;
        }

        int max_flow(int s, int t) {
            this.src = s;
            this.sink = t;
            int total_flow = 0;
            while (build_bfs()) {
                total_flow += send_flow(s, Integer.MAX_VALUE);
            }
            return total_flow;
        }
    }

    static int n;
    static final int N = 15;
    static char[][] grid = new char[N][N];
    static char[][] capsule = new char[N][N];
    static int[][] Z = new int[N][N];
    static int[][] S = new int[N][N];
    static int[] dx = {-1, 1, 0, 0};
    static int[] dy = {0, 0, -1, 1};
    static MaxFlow flow;
    static int T;
    static final int INF = 1000000000;

    static boolean inside(int i, int j) {
        return i >= 0 && i < n && j >= 0 && j < n;
    }

    static boolean is_digit(char ch) {
        return ch >= '1' && ch <= '9';
    }

    static void perform_bfs(int x, int y, int[][] dist_map, boolean mark) {
        int start_x = x, start_y = y;
        for (int[] row : dist_map) {
            Arrays.fill(row, 0x3f3f3f3f);
        }
        dist_map[x][y] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(x);
        q.offer(y);
        if (mark && is_digit(capsule[x][y])) {
            flow.add_edge(start_x * n + start_y, start_x * n + start_y + n * n, INF);
        }
        while (!q.isEmpty()) {
            x = q.poll();
            y = q.poll();
            if (dist_map[x][y] == T) break;
            for (int o = 0; o < 4; o++) {
                int xx = x + dx[o], yy = y + dy[o];
                if (inside(xx, yy) && dist_map[xx][yy] == 0x3f3f3f3f && capsule[xx][yy] != 'Y') {
                    if (Z[xx][yy] > dist_map[x][y] + 1 || (Z[xx][yy] == dist_map[x][y] + 1 && is_digit(capsule[xx][yy]))) {
                        dist_map[xx][yy] = dist_map[x][y] + 1;
                        if (mark && is_digit(capsule[xx][yy])) {
                            flow.add_edge(start_x * n + start_y, xx * n + yy + n * n, INF);
                        }
                        if (Z[xx][yy] > dist_map[x][y] + 1 || !mark) {
                            q.offer(xx);
                            q.offer(yy);
                        }
                    }
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        T = Integer.parseInt(st.nextToken());
        int s_node = n * n * 2;
        int t_node = s_node + 1;
        flow = new MaxFlow(s_node + 2);
        int x = -1, y = -1;
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            grid[i] = line.toCharArray();
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'Z') {
                    x = i;
                    y = j;
                }
            }
        }
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            capsule[i] = line.toCharArray();
            for (int j = 0; j < n; j++) {
                if (is_digit(capsule[i][j])) {
                    flow.add_edge(i * n + j + n * n, t_node, capsule[i][j] - '0');
                }
            }
        }
        perform_bfs(x, y, Z, false);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (is_digit(grid[i][j])) {
                    flow.add_edge(s_node, i * n + j, grid[i][j] - '0');
                    perform_bfs(i, j, S, true);
                }
            }
        }
        System.out.println(flow.max_flow(s_node, t_node));
    }
}

